INSERT INTO nhs_groups (id, group_code, slug, icon, tag_en, tag_tl, title_en, title_tl, desc_en, desc_tl, status, build_progress, recommended_for_recruit, accent_color, sort_order) VALUES
(1, '00', 'hardware',  '🔧', 'Group 00 · Start Here', 'Pangkat 00 · Magsimula Dito', 'Hardware Group',            'Hardware Group',            'The foundation of everything. Hardware Group teaches what a computer is, how to build one from scratch, and how to keep machines running.', 'Ang pundasyon ng lahat. Ang Hardware Group ay nagtuturo kung ano ang isang computer, paano ito buuin mula sa simula, at paano ito panatilihing gumagana.', 'open',    100, 1, '#4ade80', 0),
(2, '01', 'iot',       '🌐', 'Group 01',              'Pangkat 01',                  'I.O.T Group',               'I.O.T Group',               'Internet of Things — connecting physical sensors and devices to the digital world.',                                                        'Internet of Things — pagkokonekta ng mga pisikal na sensor at device sa digital na mundo.',                                                             'standby', 35,  0, '#c084fc', 1),
(3, '02', 'network',   '📡', 'Group 02',              'Pangkat 02',                  'Network Group',             'Network Group',             'Managing the pathways data travels on — Wi-Fi planning, switches, VLANs, and routers.',                                                     'Pamamahala ng mga landas na tinatahak ng datos — Wi-Fi, switches, VLANs, at routers.',                                                                  'standby', 45,  0, '#38bdf8', 2),
(4, '03', 'admin',     '🗂️', 'Group 03',              'Pangkat 03',                  'Admin Group',               'Admin Group',               'Managing processes, documentation, ticketing, and operational systems across NHS.',                                                         'Pamamahala ng mga proseso, dokumentasyon, ticketing, at sistema ng operasyon sa NHS.',                                                                  'standby', 30,  0, '#4ade80', 3),
(5, '04', 'inventory', '📦', 'Group 04',              'Pangkat 04',                  'Inventory Group',           'Inventory Group',           'Tracking, auditing, and managing all physical hardware assets and lifecycle records.',                                                      'Pagsubaybay at pamamahala ng lahat ng pisikal na kagamitan at kondisyon ng hardware.',                                                                   'standby', 25,  0, '#fb923c', 4),
(6, '05', 'itinfra',   '🖥️', 'Group 05',              'Pangkat 05',                  'I.T. Infrastructure Group', 'I.T. Infrastructure Group', 'Building skills in servers, Proxmox virtual machines, Linux, networking, SQL databases, and security.',                                     'Pagtatayo ng mga kasanayan sa mga server, Proxmox virtual machine, Linux, networking, SQL database, at seguridad.',                                      'open',    100, 0, '#f0a500', 5);
