INSERT INTO recruit_onboarding_tasks (id, task_key, title_en, title_tl, desc_en, desc_tl, sort_order) VALUES
(1, 'read_hierarchy', 'Understand SFM → STF → NHS', 'Unawain ang SFM → STF → NHS', 'Learn how NHS fits inside the Special Task Force and School For Ministers.', 'Alamin kung paano nakapaloob ang NHS sa Special Task Force at School For Ministers.', 1),
(2, 'explore_6_groups', 'Review All 6 NHS Groups (00–05)', 'Suriin ang Anim na Pangkat ng NHS (00–05)', 'Read the mission of each of the 6 specialized groups to see how they collaborate.', 'Basahin ang tungkulin ng bawat isa sa 6 na espesyalisadong pangkat.', 2),
(3, 'complete_hw_lesson1', 'Complete Hardware Track 01 · Lesson 01', 'Tapusin ang Hardware Track 01 · Aralin 01', 'Open the in-app Lesson Viewer in Hardware Group and finish your first lesson on computer anatomy.', 'Buksan ang Lesson Viewer sa Hardware Group at tapusin ang unang aralin.', 3),
(4, 'complete_proxmox_intro', 'Complete Proxmox VE · Lesson 01', 'Tapusin ang Proxmox VE · Aralin 01', 'Learn how virtualization lets one physical server run multiple isolated machines.', 'Alamin kung paano hinahati ng Proxmox ang isang server sa maraming virtual machine.', 4),
(5, 'select_primary_group', 'Choose Your Primary Cross-Training Path', 'Piliin ang Iyong Pangunahing Pangkat', 'Coordinate with your group lead or Sector 111 Admin to confirm your track assignment.', 'Makipag-ugnayan sa iyong group lead o Sector 111 Admin para sa iyong unang proyekto.', 5);
INSERT INTO announcements (id, author_user_id, target_audience, badge_label, title_en, title_tl, body_en, body_tl, is_pinned) VALUES
(1, 1, 'all', 'SYSTEM UPDATE', '6-Group Orientation Portal & In-App Lesson Viewer Live', 'Bukas Na ang 6-Group Portal at In-App Lesson Viewer', 'Welcome to the upgraded NHS Orientation Portal! All 12 Proxmox VE lessons and foundational Hardware tracks are now viewable directly inside the app with SQL progress tracking.', 'Maligayang pagdating sa bagong NHS Orientation Portal! Ang lahat ng 12 aralin sa Proxmox VE at Hardware tracks ay mabubuksan na mismo sa loob ng app.', 1),
(2, 1, 'member', 'CROSS-TRAINING', 'Member Cross-Training Open for Group 05 (Proxmox & SQL)', 'Cross-Training para sa Group 05 (Proxmox at SQL)', 'Existing NHS members can now jump straight from the Member Dashboard into Proxmox VE, Linux CLI, and SQL Database Management tracks.', 'Maaari nang dumiretso ang mga dating miyembro mula sa Member Dashboard patungo sa Proxmox VE, Linux CLI, at SQL Database Management.', 0);
